  }

  &__headline {
    color: var(--clr-white);
  }

  &__sub {
    margin-top: fluid(12, 20);
    color: rgba(255, 255, 255, 0.6);
  }

  &__canvas-wrap {
    position: absolute;
    inset: 0;
    z-index: 1;

    canvas {
      display: block;
      width: 100%;
      height: 100%;
    }
