163	function syncSectionTextReveal(
164	  selector: string,
165	  domState: { visible: boolean; timers: number[] },
166	  progress: number,
167	): void {
168	  const shouldShow = progress >= SECTION_TEXT_REVEAL_THRESHOLD;
169	  const shouldHide = !shouldShow && progress < SECTION_TEXT_HIDE_THRESHOLD;
170	  if (!shouldShow && !shouldHide) return;
171	  if (domState.visible === shouldShow) return;
